## ----setup-architecture-chap--------------------------------------------------
library(knitr)
library(ggplot2)
library(mlr3)
library(mlr3learners)
library(xplainfi)

knitr::opts_chunk$set(
  echo = TRUE,
  warning = FALSE,
  message = FALSE
)
options(digits = 3)
options(scipen = 5)
options(
  datatable.print.keys = FALSE,
  datatable.print.class = FALSE
)


## ----mlr3-demo----------------------------------------------------------------
#| cache: true
library(mlr3learners) # loads mlr3
set.seed(2026)        # for reproducibility
rr <- resample(
  learner = lrn("classif.ranger", num.trees = 100),
  task = tsk("penguins"),
  resampling = rsmp("cv", folds = 5))
rr$score(msr("classif.ce"))
rr$aggregate(msr("classif.ce"))


## ----pfi-demo-model-----------------------------------------------------------
#| echo: true
#| cache: false
library(xplainfi)
task <- sim_dgp_correlated(n = 5000, r = 0.8)
lrn_ranger <- lrn("regr.ranger")
resampling_ho <- rsmp("holdout")$instantiate(task)
lrn_ranger$train(task, row_ids = resampling_ho$train_set(1))

pfi_model <- PFI$new(
  task = task, learner = lrn_ranger, measure = msr("regr.mse"),
  resampling = resampling_ho, n_repeats = 10)
pfi_model$compute()
pfi_model$importance()


## ----pfi-demo-learner---------------------------------------------------------
#| echo: true
pfi <- PFI$new(
  task = task, learner = lrn("regr.ranger"), measure = msr("regr.mse"),
  resampling = rsmp("cv", folds = 3), n_repeats = 10)
pfi$compute()
pfi$importance()


## ----pfi-demo-scores----------------------------------------------------------
head(pfi$scores(), 3)


## ----pfi-demo-swap-1----------------------------------------------------------
#| echo: true
pfi <- PFI$new(
  task = task,
  learner = lrn("regr.xgboost", eta = 0.01, nrounds = 1000),
  measure = msr("regr.mae"),
  resampling = rsmp("subsampling", repeats = 10),
  n_repeats = 15)
pfi$compute()
pfi$importance()


## ----pfi-demo-tuned-----------------------------------------------------------
#| echo: true
#| cache: false
library(mlr3tuning)
lrn_tuned <- auto_tuner(
  learner = lrn("regr.ranger", min.node.size = to_tune(1, 50)),
  resampling = rsmp("cv", folds = 3), measure = msr("regr.mse"),
  tuner = tnr("grid_search", resolution = 10), term_evals = 10)

pfi <- PFI$new(
  task = task, learner = lrn_tuned, measure = msr("regr.mse"),
  resampling = rsmp("cv", folds = 3), n_repeats = 10)
pfi$compute()
pfi$importance()


## ----cfi-demo-----------------------------------------------------------------
#| echo: true
#| cache: true
cfi <- CFI$new(
  task = task, learner = lrn("regr.ranger"), measure = msr("regr.mse"),
  resampling = rsmp("subsampling", repeats = 5),
  sampler = ConditionalGaussianSampler$new(task),
  n_repeats = 10)
cfi$compute()
cfi$importance(ci_method = "quantile", alternative = "two.sided")


## ----pfi-inference------------------------------------------------------------
#| echo: true
head(pfi$importance(ci_method = "nadeau_bengio"), 3)


## ----pfi-inference-comparison-plot--------------------------------------------
#| echo: false
#| fig.height: 2.5
#| fig.align: "center"
#| fig.cap: Comparison of uncertainty quantification methods using PFI on the correlated task (omitting noise features). Empirical 95% quantiles fall between the very narrow unadjusted confidence intervals and the wider Nadeau-Bengio-corrected intervals, which show the uncertainty masked by the unadjusted method.
#| fig.alt: Dot and whisker plot showing point estimates and error bars of the different methods, with the unadjusted being the narrowest and quantile intervals slightly narrower than the Nadeau & Bengio adjusted intervals being much wider.
data.table::rbindlist(list(
  pfi$importance(ci_method = "nadeau_bengio", alternative = "two.sided")[, method := "Nadeau & Bengio"][],
  pfi$importance(ci_method = "raw", alternative = "two.sided")[, method := "Unadjusted"][],
  pfi$importance(ci_method = "quantile", alternative = "two.sided")[, method := "Quantiles"][]
), fill = TRUE) |>
  dplyr::filter(feature %in% c("x1", "x3")) |>
  ggplot(aes(y = feature, x = importance, color = method, fill = method)) +
  # coord_cartesian(xlim = c(0, NA)) +
  geom_point(shape = 21, size = 2, position = position_dodge(width = .7)) +
  geom_errorbar(
    aes(xmin = conf_lower, xmax = conf_upper),
    position = position_dodge(width = .7),
    orientation = "y"
  ) +
  scale_color_brewer(palette = "Dark2", aesthetics = c("color", "fill")) +
  labs(
    title = NULL,
    x = "Importance (PFI)",
    y = "Feature",
    color = NULL,
    fill = NULL
  ) +
  theme_minimal(base_size = 12) +
  theme(legend.position = "bottom")


