## ----setup-section-05---------------------------------------------------------
#| echo: false
knitr::opts_chunk$set(cache = TRUE, echo = FALSE)

library(ggplot2)
library(data.table)
library(dplyr)
library(kableExtra)
# https://coolors.co/1e3888-ef476f-f5e663-ffad69-9c3848
pal_package <- c(
  xplainfi = "#1e3888",
  fippy = "#8CD867",
  vip = "#A31621",
  iml = "#ffad69",
  sage = "#EF476F"
)
source("paper_2025_xplainfi_benchmark/R/plotting.R")
source("paper_2025_xplainfi_benchmark/R/clean-results.R")

# Get result files either from locally stored results or from included benchmark
importance_stored <- "results/importances.rds"
importance_bm <- "paper_2025_xplainfi_benchmark/results/importance/importances.rds"

if (file.exists(importance_stored)) {
  importances <- readRDS(importance_stored)
} else if (file.exists(importance_bm)) {
  importances <- readRDS(importance_bm)
} else {
  stop("Can't find importances.rds")
}
# Earlier SAGE runs were superseded by a re-run; keep the newest run per cell.
importances <- dedup_latest_run(importances)

runtime_stored <- "results/runtime.rds"
runtime_bm <- "paper_2025_xplainfi_benchmark/results/runtime/runtime.rds"

if (file.exists(runtime_stored)) {
  runtime <- readRDS(runtime_stored)
} else if (file.exists(runtime_bm)) {
  runtime <- readRDS(runtime_bm)
} else {
  stop("Can't find runtime.rds")
}



