  "mSAGE" , "xplainfi, fippy"           , "Importance: n\\_permutations = 100, n\\_samples = 100, min\\_permutations = 20\nRuntime: n\\_permutations = \\{10, 20, 50\\}, n\\_samples = \\{10, 50, 100\\}",
  "mSAGE" , "sage"                      , "Importance: n\\_samples = 100\nRuntime: n\\_samples = \\{10, 50, 100\\}",
