  }) |>
  kbl(
    col.names = c("Method", "Packages", "Parameters"),
    caption = "Methods, implementations, and parameters for both benchmarks. Parameter names correspond to xplainfi's API and are set equivalently in other implementations. For the importance benchmark, early stopping was enabled for mSAGE and cSAGE in xplainfi and fippy; for the runtime benchmark, it was disabled to ensure identical workloads.",
    booktabs = TRUE,
    escape = FALSE
  ) |>
  column_spec(1, width = "1cm") |>
