## ----plot-importance-correlated-all-------------------------------------------
#| echo: false
#| fig.height: 7
#| fig.width: 10
#| fig.cap: Importance scores (scaled to percentages) for PFI, CFI, mSAGE, and cSAGE across implementations on the correlated simulation setting with r = 0.75, based on either the linear model or the boosting learner.
#| fig.alt: Boxplots of scaled importance scores by feature, colored by implementing package. x1 has the highest importance at 100, and x2 and x4 have an importance of 0. vip shows slightly higher importance for x3. xplainfi and fippy show identical values. cSAGE assigns importance to x2 similar in magnitude to x3.

plot_importance(
  importances[correlation == 0.75],
  type = "scaled",
  problem = "correlated",
  method = c("PFI", "CFI", "mSAGE", "cSAGE"),
  learner_type = c("linear", "boosting"),
  facets = c("method", "learner_type"),
  multi_line = FALSE,
  ncol = 4
)


## ----plot-importance-bikesharing-pficfi---------------------------------------
#| echo: false
#| fig.height: 7
#| fig.width: 8
#| fig.cap: Importance scores (scaled to percentages) for PFI and CFI across implementations on the bike sharing dataset, based on either the linear model or the boosting learner.
#| fig.alt: Boxplots of scaled importance scores by feature, colored by implementing package. Most features have low or zero importance. `hour` is highest, followed by `year` and `humidity`. `season` ranks lower but is nonzero only for the linear model and PFI. `apparent_temperature` also only scores around 5 with high variance for the linear model. Methods using the boosting learner assign higher importance to `working_day` and `temperature`.

plot_importance(
  importances,
  type = "scaled",
  problem = "bike_sharing",
  method = c("PFI", "CFI"),
  learner_type = c("linear", "boosting"),
  facets = c("method", "learner_type"),
  multi_line = FALSE
)


## ----plot-importance-bikesharing-sages----------------------------------------
#| echo: false
#| fig.height: 7
#| fig.width: 8
#| fig.cap: Importance scores (scaled to percentages) for mSAGE and cSAGE across implementations on the bike sharing dataset, based on either the linear model or the boosting learner.
#| fig.alt: Boxplots of scaled importance scores by feature, colored by implementing package. Similar overall picture as in the previous plot, with notably higher importances for temperature and `apparent_temperature` for the methods using the linear model. `sage` (kernel SAGE) disagrees with the other implementations both in ranking and in magnitude, showing `hour` to be close to or below 50, with `apparent_temperature` consistently at 100 when the linear model is used, while hour remains at 100 when the boosting learner is used.

plot_importance(
  importances,
  type = "scaled",
  problem = "bike_sharing",
  method = c("mSAGE", "cSAGE"),
  learner_type = c("linear", "boosting"),
  facets = c("method", "learner_type"),
  multi_line = FALSE
)


